"""Generate configs/classes.yaml: deterministic class ids from the enabled parts."""

from __future__ import annotations

import os
from typing import Any

import yaml

from screwsynth.common.io import read_yaml, write_text

from .schema import Catalogue

HEADER = (
    "# GENERATED by `screwsynth-catalogue classes` from configs/catalogue.yaml. Do not edit.\n"
    "# Class = family + size; ids are ordered by family, slot and numeric size.\n"
)


def build_classes(cat: Catalogue) -> dict[str, Any]:
    names = cat.classes()
    enabled = cat.enabled_parts
    table = []
    for i, cname in enumerate(names):
        parts = [p for p in enabled if p.class_name == cname]
        first = parts[0]
        table.append(
            {
                "id": i,
                "name": cname,
                "family": first.family,
                "kind": first.kind,
                "size": first.size,
                "parts": len(parts),
                "lengths": sorted(p.length for p in parts if p.length is not None),
            }
        )
    return {
        "catalogue_hash": cat.hash,
        "nc": len(names),
        "names": dict(enumerate(names)),
        "classes": table,
    }


def dump_classes(doc: dict[str, Any]) -> str:
    body = yaml.safe_dump(doc, sort_keys=False, default_flow_style=None, width=100)
    return HEADER + body


def write_classes(cat: Catalogue, path: str | os.PathLike[str]) -> dict[str, Any]:
    doc = build_classes(cat)
    write_text(path, dump_classes(doc))
    return doc


def classes_up_to_date(cat: Catalogue, path: str | os.PathLike[str]) -> bool:
    """True when the classes file exists and matches the current catalogue."""
    try:
        current = read_yaml(path) or {}
    except FileNotFoundError:
        return False
    return current == build_classes(cat)
